-- Restore org seed data required by locked users/customers/invoices tenant changes
-- Generated by Blueprint after a passing rehearsal on the sample data.

BEGIN;

-- Create table orgs
CREATE TABLE "orgs" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

-- Add column users.org_id
ALTER TABLE "users" ADD COLUMN "org_id" text;

-- Add column customers.org_id
ALTER TABLE "customers" ADD COLUMN "org_id" text;

-- Add column invoices.org_id
ALTER TABLE "invoices" ADD COLUMN "org_id" text;

-- Backfill users.org_id
UPDATE users SET org_id = id WHERE org_id IS NULL;

-- Backfill orgs
INSERT INTO orgs (id, name, created_at)
SELECT id, name || ' Organization', created_at
FROM users;

-- Backfill customers.org_id
UPDATE customers AS c SET org_id = u.org_id FROM users AS u WHERE c.owner_id = u.id AND c.org_id IS NULL;

-- Backfill invoices.org_id
UPDATE "invoices" s
SET "org_id" = t2."org_id"
FROM "projects" t1, "customers" t2
WHERE s."project_id" = t1."id"
  AND t1."customer_id" = t2."id";

-- Enforce users.org_id NOT NULL
ALTER TABLE "users" ALTER COLUMN "org_id" SET NOT NULL;

-- Enforce customers.org_id NOT NULL
ALTER TABLE "customers" ALTER COLUMN "org_id" SET NOT NULL;

-- Enforce invoices.org_id NOT NULL: skipped (conflict left in place)

-- Fix before "Unique users (email)": Merged 2 duplicate users into 2; repointed 2 api_keys, 4 comments, 3 customers
CREATE TEMP TABLE blueprint_merge AS
         SELECT "id" AS dupe, first_value("id") OVER (PARTITION BY lower("email"::text) ORDER BY "created_at", "id") AS keep
         FROM "users" WHERE "email" IS NOT NULL AND lower("email"::text) IN (SELECT lower("email"::text) FROM "users" GROUP BY lower("email"::text) HAVING count(*) > 1);
DELETE FROM blueprint_merge WHERE dupe = keep;
UPDATE "api_keys" r SET "user_id" = m.keep FROM blueprint_merge m WHERE r."user_id" = m.dupe;
UPDATE "comments" r SET "author_id" = m.keep FROM blueprint_merge m WHERE r."author_id" = m.dupe;
UPDATE "customers" r SET "owner_id" = m.keep FROM blueprint_merge m WHERE r."owner_id" = m.dupe;
DELETE FROM "users" t USING blueprint_merge m WHERE t."id" = m.dupe;
DROP TABLE blueprint_merge;

-- Unique users (email)
CREATE UNIQUE INDEX "users_email_lower_key" ON "users" (lower("email"));

-- Foreign key invoices.org_id → orgs.id
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id");

-- Foreign key customers.org_id → orgs.id
ALTER TABLE "customers" ADD CONSTRAINT "customers_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON DELETE RESTRICT;

COMMIT;
